import React from 'react';

/** Variant styles for the Button component. */
export type ButtonVariant = 'solid' | 'dither' | 'outline' | 'ghost' | 'inverted' | 'ascii' | 'pixel';

/** Size options for the Button component. */
export type ButtonSize = 'sm' | 'lg' | 'xl';

/** Props for the {@link Button} component. */
export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Visual variant of the button. */
  variant?: ButtonVariant;
  /** Size preset. Default renders at the base size. */
  size?: ButtonSize;
  /** Show a loading indicator and disable interaction. */
  loading?: boolean;
  /** Additional CSS class names. */
  className?: string;
  /** Button content. */
  children?: React.ReactNode;
}

/**
 * Interactive button with ASCII dither variants.
 * Renders a `<button>` with the `sk-btn` class and maps props to `data-*` attributes.
 */
export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ variant, size, loading, className, children, disabled, ...rest }, ref) => (
    <button
      ref={ref}
      className={`sk-btn${className ? ` ${className}` : ''}`}
      data-variant={variant}
      data-size={size}
      data-loading={loading ? '' : undefined}
      disabled={disabled || loading}
      {...rest}
    >
      {children}
    </button>
  ),
);

Button.displayName = 'Button';

/**
 * skeehn — Button Component
 *
 * @component sk-btn
 * @variants  solid | dither | outline | ghost | inverted | ascii | pixel | retro
 * @sizes     sm | md (default) | lg | xl
 * @states    :hover | :active | :focus-visible | :disabled | [data-loading] | [data-skeleton]
 * @a11y      Focus ring via outline, disabled opacity, aria-disabled support
 * @print     Renders as outline-only, no shadows or animations
 */
.sk-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--sk-space-2);
  padding: var(--sk-space-2) var(--sk-space-4); min-height: 2rem;
  font-family: var(--sk-font-mono); font-size: var(--sk-font-size-sm); font-weight: 500;
  letter-spacing: 0.01em; line-height: 1; border: var(--sk-border); border-radius: var(--sk-radius);
  background: transparent; cursor: pointer; user-select: none;
  transition: all var(--sk-transition); white-space: nowrap; position: relative; overflow: hidden;
}
.sk-btn:focus-visible { outline: 2px solid hsl(var(--sk-ring)); outline-offset: 2px; }

/* Chunky pixel press — universal active state */
.sk-btn:active:not(:disabled) {
  box-shadow: inset 0 2px 0 hsl(var(--sk-foreground) / 0.15);
  transform: translateY(1px);
}

.sk-btn:disabled { opacity: 0.4; pointer-events: none; cursor: not-allowed; }

/* Sizes */
.sk-btn[data-size="sm"] { padding: var(--sk-space-1) var(--sk-space-3); min-height: 1.5rem; font-size: var(--sk-font-size-xs); }
.sk-btn[data-size="lg"] { padding: var(--sk-space-3) var(--sk-space-6); min-height: 2.75rem; font-size: var(--sk-font-size-base); }
.sk-btn[data-size="xl"] { padding: var(--sk-space-4) var(--sk-space-8); min-height: 3.5rem; font-size: var(--sk-font-size-lg); }

/* Solid */
.sk-btn[data-variant="solid"] { background: hsl(var(--sk-primary)); color: hsl(var(--sk-background)); border-color: transparent; }
.sk-btn[data-variant="solid"]:hover:not(:disabled) { opacity: 0.85; }

/* Dither — denser pattern on hover, scanline texture on active */
.sk-btn[data-variant="dither"] {
  --sk-dither-opacity: 0.12;
  background: hsl(var(--sk-primary)); color: hsl(var(--sk-background)); border-color: transparent;
}
.sk-btn[data-variant="dither"]::before {
  content: ""; position: absolute; inset: 0;
  background-image: var(--sk-dither-b6, var(--sk-dither-pattern));
  background-repeat: repeat;
  opacity: var(--sk-dither-opacity);
  mix-blend-mode: overlay;
  pointer-events: none;
  transition: opacity var(--sk-transition);
}
/* Denser dither on hover */
.sk-btn[data-variant="dither"]:hover:not(:disabled) {
  --sk-dither-opacity: 0.32;
}
/* Swap to scanline feel on active */
.sk-btn[data-variant="dither"]:active:not(:disabled)::before {
  background-image: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 1px,
    hsl(var(--sk-foreground) / 0.1) 1px,
    hsl(var(--sk-foreground) / 0.1) 2px
  );
  opacity: 1;
}

/* Outline */
.sk-btn[data-variant="outline"] { background: transparent; color: hsl(var(--sk-foreground)); border-color: hsl(var(--sk-border-color)); }
.sk-btn[data-variant="outline"]:hover:not(:disabled) { background: hsl(var(--sk-accent)); border-color: hsl(var(--sk-foreground)); }

/* Ghost */
.sk-btn[data-variant="ghost"] { background: transparent; color: hsl(var(--sk-foreground)); border-color: transparent; }
.sk-btn[data-variant="ghost"]:hover:not(:disabled) { background: hsl(var(--sk-accent)); }

/* Inverted */
.sk-btn[data-variant="inverted"] { background: hsl(var(--sk-background)); color: hsl(var(--sk-foreground)); border: 2px solid hsl(var(--sk-foreground)); }
.sk-btn[data-variant="inverted"]:hover:not(:disabled) { background: hsl(var(--sk-primary)); color: hsl(var(--sk-background)); }

/* ASCII — border drawn with box-drawing chars */
.sk-btn[data-variant="ascii"] {
  background: transparent; color: hsl(var(--sk-foreground)); border: none;
  font-family: var(--sk-font-mono); padding: var(--sk-space-1) var(--sk-space-3);
}
.sk-btn[data-variant="ascii"]::before {
  content: "┌────────┐"; position: absolute; top: -0.5rem; left: 0; right: 0;
  font-size: 0.5rem; line-height: 1; color: hsl(var(--sk-border-color)); pointer-events: none;
}
.sk-btn[data-variant="ascii"]::after {
  content: "└────────┘"; position: absolute; bottom: -0.5rem; left: 0; right: 0;
  font-size: 0.5rem; line-height: 1; color: hsl(var(--sk-border-color)); pointer-events: none;
}

/* Pixel — 4px raised bevel shadow style */
.sk-btn[data-variant="pixel"] {
  background: hsl(var(--sk-background));
  color: hsl(var(--sk-foreground));
  border: 2px solid hsl(var(--sk-foreground));
  box-shadow: 4px 4px 0 hsl(var(--sk-foreground));
  /* offset: compensate so the visual bounding box stays in flow */
  transform: translate(0, 0);
  transition: box-shadow var(--sk-transition), transform var(--sk-transition);
}
.sk-btn[data-variant="pixel"]:hover:not(:disabled) {
  box-shadow: 2px 2px 0 hsl(var(--sk-foreground));
  transform: translate(2px, 2px);
}
.sk-btn[data-variant="pixel"]:active:not(:disabled) {
  box-shadow: 0 0 0 hsl(var(--sk-foreground));
  transform: translate(4px, 4px);
  /* override the universal active shadow so it doesn't double-apply */
  /* inset shadow omitted for clean flat-press feel on pixel variant */
}
/* pixel variant neutralises the universal inset press */
.sk-btn[data-variant="pixel"]:active:not(:disabled) {
  box-shadow: 0 0 0 hsl(var(--sk-foreground));
}

/* ============================================================
   LOADING STATE
   [data-loading] — animating ░▒▓█ fill indicator via ::after
   Usage: <button class="sk-btn" data-variant="solid" data-loading>…</button>
   ============================================================ */
@keyframes sk-btn-load-chars {
  0%   { content: "░"; }
  25%  { content: "▒"; }
  50%  { content: "▓"; }
  75%  { content: "█"; }
  100% { content: "░"; }
}

.sk-btn[data-loading] {
  pointer-events: none;
  opacity: 0.8;
  /* nudge label to leave room for the indicator */
  padding-right: calc(var(--sk-space-4) + 1.4em);
}
/* ascii/pixel variants keep their own padding rhythm */
.sk-btn[data-variant="ascii"][data-loading],
.sk-btn[data-variant="pixel"][data-loading] {
  padding-right: calc(var(--sk-space-3) + 1.4em);
}

.sk-btn[data-loading]::after {
  content: "░";
  position: absolute;
  right: var(--sk-space-3);
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--sk-font-mono);
  font-size: inherit;
  line-height: 1;
  pointer-events: none;
  animation: sk-btn-load-chars 0.8s steps(1) infinite;
}
/* pixel/ascii ::after is already used — loading indicator shifts to gap */
.sk-btn[data-variant="ascii"][data-loading]::after,
.sk-btn[data-variant="ascii"][data-loading]::before {
  /* restore ascii decorators and suppress the loading override */
}
/* for ascii, use the gap slot instead */
.sk-btn[data-variant="ascii"][data-loading] {
  /* inherit default loading ::after — ascii border decorators use top/bottom not right */
}

/* ============================================================
   MICRO-INTERACTIONS
   ============================================================ */

.sk-btn:hover:not(:disabled):not([data-variant="pixel"]):not([data-variant="ascii"]) {
  transform: translateY(-1px);
}

.sk-btn:focus-visible {
  outline: 2px solid hsl(var(--sk-ring));
  outline-offset: 2px;
  box-shadow: 0 0 0 4px hsl(var(--sk-ring) / 0.12);
}

/* ============================================================
   SKELETON STATE
   [data-skeleton] — shimmer placeholder before content loads
   ============================================================ */

@keyframes sk-btn-skeleton-shimmer {
  0%   { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

.sk-btn[data-skeleton] {
  pointer-events: none;
  color: transparent;
  border-color: hsl(var(--sk-border-color));
  background:
    linear-gradient(
      90deg,
      hsl(var(--sk-muted)) 25%,
      hsl(var(--sk-accent)) 50%,
      hsl(var(--sk-muted)) 75%
    );
  background-size: 200% 100%;
  animation: sk-btn-skeleton-shimmer 1.8s ease-in-out infinite;
}

.sk-btn[data-skeleton]::before,
.sk-btn[data-skeleton]::after {
  display: none;
}

/* ============================================================
   RETRO VARIANT — CRT glow + scanlines
   ============================================================ */

.sk-btn[data-variant="retro"] {
  background: hsl(var(--sk-primary));
  color: hsl(var(--sk-background));
  border: 2px solid hsl(var(--sk-primary));
  text-shadow: 0 0 4px hsl(var(--sk-primary) / 0.6);
  box-shadow:
    0 0 6px hsl(var(--sk-primary) / 0.15),
    inset 0 0 12px hsl(var(--sk-primary) / 0.05);
  position: relative;
}

.sk-btn[data-variant="retro"]::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 2px,
    hsl(var(--sk-background) / 0.06) 2px,
    hsl(var(--sk-background) / 0.06) 3px
  );
  pointer-events: none;
  border-radius: inherit;
}

.sk-btn[data-variant="retro"]:hover:not(:disabled) {
  box-shadow:
    0 0 10px hsl(var(--sk-primary) / 0.3),
    inset 0 0 16px hsl(var(--sk-primary) / 0.08);
  text-shadow: 0 0 8px hsl(var(--sk-primary) / 0.8);
}

/* ============================================================
   PRINT OPTIMIZATION
   ============================================================ */

@media print {
  .sk-btn {
    box-shadow: none;
    text-shadow: none;
    background: transparent;
    color: hsl(var(--sk-foreground));
    border: 1px solid hsl(var(--sk-foreground));
  }
  .sk-btn::before,
  .sk-btn::after {
    display: none;
  }
  .sk-btn[data-skeleton],
  .sk-btn[data-loading] {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sk-btn { transition: none; }
  .sk-btn:hover:not(:disabled) { transform: none; }
  .sk-btn:active:not(:disabled) { transform: none; }
  .sk-btn[data-skeleton] { animation: none; background: hsl(var(--sk-muted)); }
  .sk-btn[data-loading]::after { animation: none; }
}
